    col: [['book a flight', 'reys band qilmoq', 'I *booked a flight* to Rome.'], ['pack your bags', 'sumkalarni yig‘moq', 'Don’t forget to *pack your bags*.'], ['go sightseeing', 'diqqatga sazovor joylarni ko‘rmoq', 'We *went sightseeing* all day.'], ['take a taxi', 'taksiga chiqmoq', 'Let’s *take a taxi* to the hotel.']],
    pv: [['set off', 'yo‘lga chiqmoq', 'We *set off* at dawn.'], ['check in / check out', 'ro‘yxatdan o‘tmoq / chiqmoq', 'You must *check out* by noon.'], ['see off', 'kuzatib qo‘ymoq', 'My family *saw* me *off* at the airport.'], ['pick up', 'olib ketmoq (kutib olmoq)', 'A driver will *pick* you *up*.']],
    use: [['trip vs. journey vs. travel', 'trip — borib kelish; journey — yo‘l (bir joydan ikkinchisiga); travel — fe’l / umumiy sayohat.', ['We took a day *trip* to Bukhara.', 'The *journey* took ten hours.']],
          ['tour vs. excursion', 'tour — uzoqroq uyushtirilgan sayohat; excursion — qisqa ekskursiya.', ['We went on a two-week *tour*.', 'The school organised an *excursion*.']]],
